// Normalize PagerDuty payload to our standard alert format
const body = $input.first().json.body || $input.first().json;

// Handle both real PagerDuty v3 webhooks and our mock format
const alert = body.messages?.[0]?.event?.data || body;

return [{
  json: {
    id: alert.id || 'PD-UNKNOWN',
    title: alert.title || alert.summary || 'Unknown alert',
    severity: alert.severity || 'P2',
    service: alert.service?.name || alert.service || 'unknown',
    environment: alert.environment || 'production',
    cluster: alert.cluster || 'prod-eks',
    namespace: alert.namespace || 'prod',
    triggered_at: alert.triggered_at || new Date().toISOString(),
    details: alert.details || alert.body?.details_summary || ''
  }
}];

// Parse the JSON output from the Python agent
const stdout = $input.first().json.stdout;
try {
  const result = JSON.parse(stdout);
  return [{ json: result }];
} catch (e) {
  throw new Error('Agent output parse error: ' + e.message + '\nRaw output: ' + stdout);
}

